-- Catálogo general transcrito de las seis capturas aprobadas por el usuario.
-- Dos filas tienen orden 81; sus identidades son diferentes.
ALTER TABLE rubro_presupuestal ADD COLUMN eliminado BOOLEAN NOT NULL DEFAULT FALSE;

-- Conservar la configuración efectiva de los años existentes antes de cambiar la base.
SELECT r.codigo,r.nombre,r.descripcion,0,TRUE,TRUE,r.activo,r.orden,v.id,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
FROM rubro_presupuestal r CROSS JOIN vigencia v
WHERE r.vigencia_id IS NULL AND r.codigo LIKE 'FORM.CONCEPTO.%'
AND NOT EXISTS (SELECT 1 FROM rubro_presupuestal own WHERE own.vigencia_id=v.id AND own.codigo=r.codigo)
AND NOT EXISTS (SELECT 1 FROM necesidad_presupuestal n WHERE n.vigencia_id=v.id AND n.rubro_presupuestal_id=r.id);

-- Los conceptos personalizados creados en un año también forman parte del catálogo general.
SELECT r.codigo,UPPER(r.nombre),r.descripcion,0,TRUE,TRUE,r.activo,r.orden,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
FROM rubro_presupuestal r WHERE r.vigencia_id IS NOT NULL AND r.codigo LIKE 'FORM.CONCEPTO.%'
AND r.id=(SELECT MAX(last_copy.id) FROM rubro_presupuestal last_copy WHERE last_copy.codigo=r.codigo AND last_copy.vigencia_id IS NOT NULL)
AND NOT EXISTS (SELECT 1 FROM rubro_presupuestal base WHERE base.codigo=r.codigo AND base.vigencia_id IS NULL);

-- Retirar las 65 plantillas originales sin renombrar IDs que puedan tener históricos.
UPDATE rubro_presupuestal SET activo=FALSE,eliminado=TRUE,updated_at=CURRENT_TIMESTAMP
WHERE vigencia_id IS NULL AND codigo IN ('FORM.CONCEPTO.001','FORM.CONCEPTO.002','FORM.CONCEPTO.003','FORM.CONCEPTO.004','FORM.CONCEPTO.005','FORM.CONCEPTO.006','FORM.CONCEPTO.007','FORM.CONCEPTO.008','FORM.CONCEPTO.009','FORM.CONCEPTO.010','FORM.CONCEPTO.011','FORM.CONCEPTO.012','FORM.CONCEPTO.013','FORM.CONCEPTO.014','FORM.CONCEPTO.015','FORM.CONCEPTO.016','FORM.CONCEPTO.017','FORM.CONCEPTO.018','FORM.CONCEPTO.019','FORM.CONCEPTO.020','FORM.CONCEPTO.021','FORM.CONCEPTO.022','FORM.CONCEPTO.023','FORM.CONCEPTO.024','FORM.CONCEPTO.025','FORM.CONCEPTO.026','FORM.CONCEPTO.027','FORM.CONCEPTO.028','FORM.CONCEPTO.029','FORM.CONCEPTO.030','FORM.CONCEPTO.031','FORM.CONCEPTO.032','FORM.CONCEPTO.033','FORM.CONCEPTO.034','FORM.CONCEPTO.035','FORM.CONCEPTO.036','FORM.CONCEPTO.037','FORM.CONCEPTO.038','FORM.CONCEPTO.039','FORM.CONCEPTO.040','FORM.CONCEPTO.041','FORM.CONCEPTO.042','FORM.CONCEPTO.043','FORM.CONCEPTO.044','FORM.CONCEPTO.045','FORM.CONCEPTO.046','FORM.CONCEPTO.047','FORM.CONCEPTO.048','FORM.CONCEPTO.049','FORM.CONCEPTO.050','FORM.CONCEPTO.051','FORM.CONCEPTO.052','FORM.CONCEPTO.053','FORM.CONCEPTO.054','FORM.CONCEPTO.055','FORM.CONCEPTO.056','FORM.CONCEPTO.057','FORM.CONCEPTO.058','FORM.CONCEPTO.059','FORM.CONCEPTO.060','FORM.CONCEPTO.061','FORM.CONCEPTO.062','FORM.CONCEPTO.063','FORM.CONCEPTO.064','FORM.CONCEPTO.065');


